#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    #[derive(serde::Deserialize)]
    #[serde(deny_unknown_fields)]
    struct Record {
        cursorcraft: String,
        #[serde(default)]
        cursor: Vec<Entry>,
    }

    #[derive(serde::Deserialize)]
    #[serde(deny_unknown_fields)]
    struct Entry {
        id: String,
        id_fp: Option<String>,
        info_fp: String,
        status: Status,
        #[serde(default)]
        slots: Vec<Cursor>,
        note: String,
    }

    #[derive(serde::Deserialize, PartialEq, Debug)]
    #[serde(rename_all = "lowercase")]
    enum Status {
        Wired,
        Skipped,
        Needed,
        Obsolete,
    }

    fn record() -> Record {
        toml::from_str(include_str!("cursors.toml")).expect("cursors.toml parses")
    }

    #[test]
    fn the_record_names_its_source_and_each_id_once() {
        let r = record();
        assert!(!r.cursorcraft.is_empty());
        let mut seen = HashMap::new();
        for e in &r.cursor {
            assert!(seen.insert(e.id.as_str(), ()).is_none(), "{} recorded twice", e.id);
            check_entry(e);
        }
    }

    /// One record entry's fields agree with its status.
    fn check_entry(e: &Entry) {
        assert!(!e.id.is_empty() && e.id.chars().all(|c| c.is_ascii_alphanumeric()), "{}: an id, not a file name", e.id);
        assert!(!e.note.trim().is_empty() && e.info_fp.len() == 8, "{}: note and info_fp", e.id);
        match e.status {
            Status::Wired | Status::Skipped => assert!(e.id_fp.is_some(), "{}: a drawn cursor records its id_fp", e.id),
            Status::Needed => assert!(e.id_fp.is_none(), "{}: a request has no id_fp yet", e.id),
            Status::Obsolete => {} // a withdrawn request, drawn or not
        }
        assert_eq!(e.slots.is_empty(), matches!(e.status, Status::Skipped | Status::Obsolete), "{}: slots", e.id);
    }

    /// A withdrawn request was usually never drawn: it has no drawing to fingerprint.
    #[test]
    fn an_obsolete_request_needs_no_drawing_fingerprint() {
        let r: Record =
            toml::from_str("cursorcraft = \"x\"\n[[cursor]]\nid = \"Lasso\"\ninfo_fp = \"12345678\"\nstatus = \"obsolete\"\nnote = \"Withdrawn.\"\n")
                .unwrap();
        check_entry(&r.cursor[0]);
    }

    /// An id is the cursor's name in VectorCraft (its `Cursor` value), never a file name.
    #[test]
    #[should_panic(expected = "an id, not a file name")]
    fn an_id_is_a_name_not_a_file() {
        let r: Record = toml::from_str(
            "cursorcraft = \"x\"\n[[cursor]]\nid = \"Lasso.svg\"\nid_fp = \"12345678\"\ninfo_fp = \"12345678\"\nstatus = \"skipped\"\nnote = \"No tool.\"\n",
        )
        .unwrap();
        check_entry(&r.cursor[0]);
    }

    #[test]
    fn every_generated_glyph_is_recorded_as_wired_with_its_fingerprint() {
        let r = record();
        for (c, g) in GENERATED {
            let e = r.cursor.iter().find(|e| e.id == g.id).unwrap_or_else(|| panic!("{c:?}: {} not in cursors.toml", g.id));
            assert_eq!(e.status, Status::Wired, "{}", g.id);
            assert_eq!(e.id_fp.as_deref(), Some(g.fp), "{}: regenerate it (stale or hand-edited)", g.id);
            assert!(e.slots.contains(c), "{}: {c:?} isn't in its recorded slots", g.id);
        }
    }

    #[test]
    fn every_wired_entry_has_exactly_its_slots_in_generated() {
        for e in record().cursor.iter().filter(|e| e.status == Status::Wired) {
            let wired: Vec<Cursor> = GENERATED.iter().filter(|(_, g)| g.id == e.id).map(|&(c, _)| c).collect();
            assert_eq!(wired.len(), e.slots.len(), "{}: GENERATED has {wired:?}, record has {:?}", e.id, e.slots);
            assert!(e.slots.iter().all(|s| wired.contains(s)), "{}: GENERATED has {wired:?}, record has {:?}", e.id, e.slots);
        }
    }

    /// cursorcraft's data fingerprint (`emit::data_fingerprint`): FNV-1a over, part by part, a
    /// kind byte (0 fill, 1 stroke), white, closed (1 for fills), the width (0 for fills) and the
    /// point count, then the points, then the triangles; widths and coordinates as little-endian i32
    /// hundredths, counts as u32, indices as u16.
    fn data_fingerprint(g: &Glyph) -> String {
        let hundredths = |v: f32| ((v * 100.0).round() as i32).to_le_bytes();
        let mut bytes = Vec::new();
        for part in g.parts {
            let (kind, closed, width, white) = match part {
                GlyphPart::Fill { white, .. } => (0u8, true, 0.0, *white),
                GlyphPart::Stroke { closed, width, white, .. } => (1, *closed, *width, *white),
            };
            let (GlyphPart::Fill { points, .. } | GlyphPart::Stroke { points, .. }) = part;
            let tris: &[[u16; 3]] = if let GlyphPart::Fill { tris, .. } = part { tris } else { &[] };
            bytes.extend([kind, u8::from(white), u8::from(closed)]);
            bytes.extend(hundredths(width));
            bytes.extend((points.len() as u32).to_le_bytes());
            for &(x, y) in points.iter() {
                bytes.extend(hundredths(x));
                bytes.extend(hundredths(y));
            }
            bytes.extend(tris.iter().flatten().flat_map(|i| i.to_le_bytes()));
        }
        let mut h: u64 = 0xcbf2_9ce4_8422_2325;
        for b in bytes {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x0100_0000_01b3);
        }
        format!("{:08x}", h >> 32)
    }

    #[test]
    fn every_generated_glyph_is_as_generated() {
        for (c, g) in GENERATED {
            assert_eq!(data_fingerprint(g), g.data_fp, "{c:?} ({}): edited by hand? Regenerate it with cursorcraft gen", g.id);
        }
    }

    #[test]
    fn no_cursor_has_two_generated_glyphs() {
        for (i, (c, _)) in GENERATED.iter().enumerate() {
            assert!(!GENERATED[..i].iter().any(|(k, _)| k == c), "{c:?} appears twice in GENERATED");
        }
    }

    #[test]
    fn generated_glyph_data_is_well_formed() {
        for (c, g) in GENERATED {
            assert!(!g.parts.is_empty(), "{c:?}");
            for part in g.parts {
                let (GlyphPart::Fill { points, .. } | GlyphPart::Stroke { points, .. }) = part;
                assert!(points.iter().all(|(x, y)| x.is_finite() && y.is_finite() && x.abs() < 64.0 && y.abs() < 64.0), "{c:?}");
                if let GlyphPart::Fill { tris, .. } = part {
                    assert!(tris.iter().flatten().all(|&i| usize::from(i) < points.len()), "{c:?}: triangle index out of range");
                }
            }
        }
    }
}
